"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[3580],{5597(e){e.exports=JSON.parse('{"title":"\uc11c\ubc84\ub9ac\uc2a4 \uc11c\ubc84\uc5d0 \ub300\ud55c \uc0dd\uac01","date":"2024-10-17","coverUrl":null,"html":"<h2 data-notion-block-id=\\"11de548d-8a8e-8080-b37e-db5e16bb4c14\\" id=\\"11de548d-8a8e-8080-b37e-db5e16bb4c14\\">\uc11c\ubc84\ub9ac\uc2a4 \uc11c\ubc84\uc5d0 \ub300\ud55c \uc0dd\uac01</h2><a href=\\"https://bobaekang.com/blog/serverless-servers-and-the-challenge-of-new-react-architecture/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://bobaekang.com/blog/serverless-servers-and-the-challenge-of-new-react-architecture/</a><p data-notion-block-id=\\"11de548d-8a8e-8025-be87-c431bdcf70dc\\"><b>\uc2ec\uc724\uc12d</b>: Vercel\uc758 \uc0c8 \uae30\ub2a5\uc778 <a href=\\"https://vercel.com/blog/serverless-servers-node-js-with-in-function-concurrency\\">Serverless Server</a>\uc5d0\uc11c \ube44\ub86f\ub418\ub294 \ub9ac\uc561\ud2b8\ud300\uc758 \ud480\uc2a4\ud0dd \uc544\ud0a4\ud14d\uccd0\uc5d0 \ub300\ud55c \uc0dd\uac01\uc744 \ub9d0\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. Root\uc5d0\uc11c \ub370\uc774\ud130\ub97c \ud55c\ubc88\uc5d0 \ubc1b\uc544\uc624\ub294 \ub300\uc2e0 RSC\ub97c \ud1b5\ud574 \uc218\uc2dc\ub85c \ub370\uc774\ud130\ub97c \ubc1b\uc544\uc624\ub294 \uacbd\uc6b0 Vercel \uac19\uc740 \uc778\ud504\ub77c\uc758 \ub4b7\ubc1b\uce68\uc774 \ub418\uc57c\ud558\uace0, \uc774\ub294 RSC\uc758 \uc801\uc6a9 \ube44\uc6a9(ex. <a href=\\"https://ones-to-watch.ethansup.net/news/post/ffe0e0a6901b4f3e8b9a0e48601ad787#6e1950cf-ceb7-418a-a85a-e4b7aef10d94\\">RSC\uc758 \ubd88\ud3b8\ud568</a>, <a href=\\"https://ones-to-watch.ethansup.net/news/post/d4dabcc7-9269-46bc-a2f2-ed10f9fcf35f#a7149fc6-b56a-405b-be3c-004fdbe51c8b\\">App Router\uc758 \ubd88\ud3b8\ud568</a>, \uc55e\uc11c \ub9d0\ud55c \uc778\ud504\ub77c \ubb38\uc81c\u2026)\uc5d0 \ub300\ud574 \ub2e4\uc2dc \uc0dd\uac01\ud574\ubcf4\uac8c \ub9cc\ub4ed\ub2c8\ub2e4. \ub610\ud55c <a href=\\"https://youtu.be/4PymccvinIo?si=mTqlkEVRvxQjuI2M&#x26;t=482\\">Tanstack Start\ucc98\ub7fc</a> RSC \uc911\uc2ec\uc73c\ub85c \ub9cc\ub4dc\ub294 \ub300\uc2e0 \ud074\ub77c\uc774\uc5b8\ud2b8 \uc911\uc2ec \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158\uc744 \ub9cc\ub4e4 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"11de548d-8a8e-801b-8e17-ea0eb344d3a4\\" id=\\"11de548d-8a8e-801b-8e17-ea0eb344d3a4\\">\ud658\uacbd \ubcc0\uc218\uc5d0 \ubcf4\uc548\uc744 \ucd94\uac00\ud558\uae30</h2><a href=\\"https://www.nodejs-security.com/blog/do-not-use-secrets-in-environment-variables-and-here-is-how-to-do-it-better\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.nodejs-security.com/blog/do-not-use-secrets-in-environment-variables-and-here-is-how-to-do-it-better</a><p data-notion-block-id=\\"6ede0189-e12b-411c-9478-0b20e1815f80\\">\ud658\uacbd\ubcc0\uc218\uc5d0 \ub300\ud55c \ud45c\uc900\uc740 \uc5c6\uc2b5\ub2c8\ub2e4. \uadf8\ub798\uc11c \uc720\ucd9c\ub418\ub294 \uc0c1\ud669\uc774 \ub9ce\uc774 \ud3bc\uccd0\uc9c0\uc8e0. \uc774 \uae00\uc740 \uc5ec\ub7ec\uac00\uc9c0 \uc720\ucd9c \uacbd\ub85c\ub97c \uc548\ub0b4\ud569\ub2c8\ub2e4. \ud658\uacbd\ubcc0\uc218\uac00 \uc81c\ub300\ub85c \uad00\ub9ac\ub418\uae30 \uc704\ud574\uc11c\ub294 \ud558\ub098\uc758 \ud574\uacb0\ucc45\uc740 \uc5c6\uc73c\uba70, \uc9c0\uc18d\uc801\uc778 \uad00\uc2ec\uc744 \uac00\uc9c0\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4\ub294 \uac83\uc744 \uc77c\uae68\uc6b0\ub294 \uae00\uc785\ub2c8\ub2e4. \uc774\uc804\uc5d0 \uc18c\uac1c\ud588\ub358 <a href=\\"https://ones-to-watch.ethansup.net/news/post/b251305b-8c2f-4fcc-a159-c495533e1ac4#caf1f660-0b22-4ea0-b299-ec5ccd1ea0a8\\">DMNO</a>\uac19\uc740 \ud658\uacbd\ubcc0\uc218 \uc554\ud638\ud654 \ubc0f \uc720\ud6a8\uc131 \uac80\uc0ac \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \uc0ac\uc6a9\ud558\ub294 \uac83\ub3c4 \uadf8 \uc77c\ubd80\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"11de548d-8a8e-8009-a319-c31f78d0a4c5\\" id=\\"11de548d-8a8e-8009-a319-c31f78d0a4c5\\">Local-First \uc0ac\ub840 \uc5f0\uad6c</h2><a href=\\"https://jakelazaroff.com/words/a-local-first-case-study/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://jakelazaroff.com/words/a-local-first-case-study/</a><p data-notion-block-id=\\"11de548d-8a8e-80ab-b51c-e2e19407e922\\"><a href=\\"https://ones-to-watch.ethansup.net/news/post/6631ddbe-1279-426c-88c7-e9e02785bbb6#a4c4f929-95ac-4eb6-ba62-b6bd581b3b62\\">\uc6f9\uacfc \ub2e4\ub978 \uae30\uc220\uc758 \uc735\ud569</a>\uc758 \uae00\uc4f4\uc774\uac00 Waypoint\ub77c\ub294 \uc11c\ube44\uc2a4 \uac1c\ubc1c \uacfc\uc815\uc744 \ud1b5\ud574 Local-First \uc11c\ube44\uc2a4 \uad6c\ud604 \ubc29\uc2dd\uc744 \uc124\uba85\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. <a href=\\"https://ones-to-watch.ethansup.net/news/post/0269c0cd-b5f8-4f29-8457-f7976befb282#011c26fc-e180-4b41-b912-007040d7fa76\\">\ud611\uc5c5 \uae30\ub2a5 \uad6c\ud604\uc744 \uc704\ud55c \uc544\ud0a4\ud14d\uccd0</a>\uc5d0\ub3c4 \ub098\uc624\ub4ef\uc774, \uc5d0\ub514\ud130\ub9c8\ub2e4 \uad6c\uc870\uac00 \ub2e4\ub974\uace0, \uad6c\ud604 \ubc29\uc2dd\uc5d0 \ub530\ub77c \uad6c\uc870\uac00 \ub2e4\ub974\ub2c8 \uad6c\ud604\ud560 \ub54c\ub294 \uc8fc\uc758\ud574\uc57c \ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"11de548d-8a8e-8030-beb5-dba55de773cb\\" id=\\"11de548d-8a8e-8030-beb5-dba55de773cb\\">\ub77c\uc774\ube0c\ub7ec\ub9ac \uc124\uce58\uc640 \ubcf4\uc548</h2><a href=\\"https://socket.dev/blog/nightmares-on-npm-how-two-malicious-packages-facilitate-data-theft-and-destruction\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://socket.dev/blog/nightmares-on-npm-how-two-malicious-packages-facilitate-data-theft-and-destruction</a><p data-notion-block-id=\\"11de548d-8a8e-8004-bdeb-ea2379033418\\">npm\uc740 \ubcf4\uc548\uc5d0 \uc548\uc804\ud55c \ud328\ud0a4\uc9c0\uac00 \uc62c\ub77c\uc624\ub294 \uacf3\uc774 \uc544\ub2d9\ub2c8\ub2e4. \uac04\ub2e8\ud558\uac8c \ud328\ud0a4\uc9c0 \uc124\uce58\uc2dc \uc548\uc804\uc744 \uae30\ud558\uc790\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"11de548d-8a8e-808d-b4c8-cb6205380e47\\" id=\\"11de548d-8a8e-808d-b4c8-cb6205380e47\\">Vite\uc758 Environment API \uc18c\uac1c</h2><a href=\\"https://green.sapphi.red/blog/increasing-vites-potential-with-the-environment-api\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://green.sapphi.red/blog/increasing-vites-potential-with-the-environment-api</a><p data-notion-block-id=\\"11de548d-8a8e-8008-ac33-fb67cb7eb4e0\\">Vite\uc758 Environment API\ub85c \uc5ec\ub7ec \ub7f0\ud0c0\uc784\uc744 \uc9c0\uc6d0\ud560 \uc218 \uc788\ub2e4\ub294 \uac83\uc744 \uacfc\uac70\uc640 \ud604\uc7ac(v6)\ub97c \ube44\uad50\ud558\uba74\uc11c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. Vite\uac00 CSR\uc77c \uacbd\uc6b0, SSR\uc77c \uacbd\uc6b0\uc758 \uad6c\uc870\ub97c \uc798 \uc124\uba85\ud558\uace0 \uc788\uc73c\ub2c8 Vite\uc758 \uad6c\uc870\ub97c \uac04\ub2e8\ud558\uac8c \uc54c\uae30\ub3c4 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"11de548d-8a8e-8077-b752-fe0592a731f2\\" id=\\"11de548d-8a8e-8077-b752-fe0592a731f2\\">React \ud1b5\ud569 \ud504\ub808\uc784\uc6cc\ud06c</h2><a href=\\"https://onestack.dev/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://onestack.dev/</a><p data-notion-block-id=\\"11de548d-8a8e-802c-a4f4-d5775a8ea9de\\"><a href=\\"https://tamagui.dev/\\">tamagui</a>(React Native\uacfc web\uc744 \ubaa8\ub450 \uc9c0\uc6d0\ud558\ub294 \uc2a4\ud0c0\uc77c \ud504\ub808\uc784\uc6cc\ud06c) \uac1c\ubc1c\uc790\uac00 \ub9cc\ub4e0 React Native\ub97c Metro \uae30\ubc18\uc774 \uc544\ub2cc Vite \uae30\ubc18\uc73c\ub85c \uc5ec\ub7ec \uae30\ub2a5\uc744 \uc81c\uacf5\ud574\uc11c \ud558\ub098\uc758 \ucf54\ub4dc\ubca0\uc774\uc2a4\ub85c \uc571\uacfc \uc6f9\uc744 \uc9c0\uc6d0\ud558\ub294 \ud504\ub808\uc784\uc6cc\ud06c\uc785\ub2c8\ub2e4. <a href=\\"https://ones-to-watch.ethansup.net/news/post/7af650fd-5dc1-48cd-8426-bd80375c3a0d#471383cb-e75b-46a6-b5db-2f11dcfca677\\">\uc774\uc804\uc5d0 \uac04\ub2e8\ud558\uac8c \uc18c\uac1c\ud588\ub358</a> React Strict DOM\uacfc \uac19\uc740 \uc6f9\uacfc \uc571\uc744 \ud558\ub098\uc758 \ucf54\ub4dc\ubca0\uc774\uc2a4\ub85c \uad00\ub9ac\ud558\uace0\uc790 \ud558\ub294 \uad6c\ud604\uccb4\uac00 \ub9ce\uc544\uc9c0\ub294\ub370, \uc9c0\ucf1c\ubcfc\ub9cc\ud558\ub2e4\uace0 \uc0dd\uac01\ud574\uc11c \uac00\uc838\uc654\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"11de548d-8a8e-8024-a9be-fad2c3d08c34\\" id=\\"11de548d-8a8e-8024-a9be-fad2c3d08c34\\">Deno 2.0</h2><a href=\\"https://deno.com/blog/v2.0\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://deno.com/blog/v2.0</a><p data-notion-block-id=\\"11de548d-8a8e-803e-92fb-e84d96732531\\">\uba4b\uc9c4 \uc0c8\ub85c\uc6b4 \uae30\ub2a5\uc774 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\uc9c0\ub9cc, node.js\uc640 npm\uc744 \ud638\ud658\ud55c\ub2e4\ub294 \uc810\uacfc, \uc5ec\ub7ec \ud544\uc218 JS \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \ud37c\uc2a4\ud2b8\ud30c\ud2f0\ub85c \uc9c0\uc6d0\ud55c\ub2e4\ub294 \uac83\uc740 \uc8fc\ubaa9\ud560\ub9cc \ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"11de548d-8a8e-80d8-af80-d0cb7ce11610\\" id=\\"11de548d-8a8e-80d8-af80-d0cb7ce11610\\">\ub9ac\uc561\ud2b8 \ub80c\ub354\ub9c1 \uac00\uc774\ub4dc</h2><a href=\\"https://ui.dev/why-react-renders\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://ui.dev/why-react-renders</a><p data-notion-block-id=\\"11de548d-8a8e-8021-a05f-cc1e38a46d1b\\">\ub9ac\ub80c\ub354\ub9c1 \ud0c0\uc774\ubc0d\uc744 \uc560\ub2c8\uba54\uc774\uc158\uacfc \ud568\uaed8 \uc798 \uc124\uba85\ud558\ub294 \uac00\uc774\ub4dc\uc785\ub2c8\ub2e4. <a href=\\"https://ones-to-watch.ethansup.net/news/post/a550d266-f5e9-45ae-b84e-2cc1a0180de2#91ac1cfb-7231-4434-aaf6-1b7471c1120c\\">React \ucc98\uc74c\ubd80\ud130 \uad6c\ud604\ud558\uae30</a>, <a href=\\"https://ones-to-watch.ethansup.net/news/post/022fc2c2-88d3-4c20-9075-defdea8ae65c#2d01841e-9fc5-4807-99d5-d8d2a73be23e\\">React \ub0b4\ubd80 \ub525 \ub2e4\uc774\ube0c</a>,  <a href=\\"https://ones-to-watch.ethansup.net/news/post/ce8b03b6-8565-440b-9d22-36c9ed0f58db#3107fecb-1574-47c1-94f0-f1a53442a6a4\\">React\uc758 \ub3d9\uc2dc\ubaa8\ub4dc \uc791\ub3d9 \uc6d0\ub9ac</a> \ub4f1 \uc5ec\ub7ec\uac00\uc9c0 \uc18c\uac1c \uac00\uc774\ub4dc\uac00 \ub9ce\uc774 \uc5ec\ub7ec\ubc88 \ub2e4\ub978 \uad00\uc810\uc5d0\uc11c \ubcf4\uba74 \uc88b\uaca0\ub124\uc694.</p><p data-notion-block-id=\\"11de548d-8a8e-807c-97db-df10a8761466\\"></p>"}')}}]);